/// <summary>
/// This class is to update the claims data with the variance amount.
/// </summary>
class METPendingVendorInvoiceClaimCalculations
{
}

Method.Source:
/// <summary>
/// Creates the claim header and lines data.
/// </summary>
/// <param name = "_invoiceInfoTable">_invoiceInfoTable</param>
public void createClaimData(VendInvoiceInfoTable _invoiceInfoTable)
{
    VendInvoiceInfoLine invoiceInfoLine;
    METMatchingVarianceDetailsHeader header;
    METMatchingVarianceDetailLines lines;

    ttsbegin;
    delete_from header
        where header.PONumber == _invoiceInfoTable.PurchId;

    delete_from lines
        where lines.InvoiceNumber == _invoiceInfoTable.Num
        && lines.VendAccountNumber == _invoiceInfoTable.InvoiceAccount;
    ttscommit;

    this.createClaimHeader(_invoiceInfoTable);

    LineNumber lineNum;

    while select invoiceInfoLine
        where invoiceInfoLine.ParmId == _invoiceInfoTable.ParmId
        && invoiceInfoLine.TableRefId == _invoiceInfoTable.TableRefId
        && (invoiceinfoLine.ReasonTableRef != 0 || invoiceinfoLine.MetPriceVarianceReasonCode != 0)
    {
        lineNum++;
        this.createClaimLines(invoiceInfoLine, _invoiceInfoTable.Num, lineNum);
    }
}

/// <summary>
/// Creates the claim header data.
/// </summary>
/// <param name = "_invoiceInfoTable">_invoiceInfoTable</param>
private void createClaimHeader(VendInvoiceInfoTable _invoiceInfoTable)
{
    METMatchingVarianceDetailsHeader header;

    header.VendAccountNumber = _invoiceInfoTable.InvoiceAccount;
    header.VendorName = VendTable::find(_invoiceInfoTable.InvoiceAccount).vendorName();
    header.InvoiceNumber = _invoiceInfoTable.Num;
    header.PONumber = _invoiceInfoTable.PurchId;
    header.VendInvTotal = _invoiceInfoTable.MetImportAmount - _invoiceInfoTable.MetImportGST;
    header.Variance = _invoiceInfoTable.METNetVariance;
    header.D365InvoiceTotal = _invoiceInfoTable.MetImportAmount - header.Variance;
    header.IntoleranceVariance = header.Variance;
    header.VendorInvoiceGST = _invoiceInfoTable.MetImportGST;
    header.D365CalculatedGST = _invoiceInfoTable.MetImportGST;
    header.GSTVariance = _invoiceInfoTable.METGSTVariance;
    header.ClaimInvoiceNumber = _invoiceInfoTable.displayClaimInvoiceNumber();
    header.insert();
}

/// <summary>
/// Creates the claim lines data.
/// </summary>
/// <param name = "_invoiceInfoLine">_invoiceInfoLine</param>
/// <param name = "_invoiceId">_invoiceId</param>
/// <param name = "_lineNum">_lineNum</param>
private void createClaimLines(VendInvoiceInfoLine _invoiceInfoLine, InvoiceId _invoiceId, LineNumber _lineNum)
{
    METMatchingVarianceDetailLines lines;
    ReasonTable reason, priceReason;
    ReasonTableRef reasonTableRef;
    RefRecId qtyReasonRef;
    RefRecId priceReasonRef;

    qtyReasonRef = _invoiceInfoLine.ReasonTableRef;
    priceReasonRef = _invoiceInfoLine.MetPriceVarianceReasonCode;

    if (qtyReasonRef)
    {
        select firstonly Reason, METClaim, METVarianceType from reason
            exists join reasonTableRef
            where reasonTableRef.Reason == reason.Reason
                && reasonTableRef.RecId == qtyReasonRef;
    }

    if (priceReasonRef)
    {
        select firstonly Reason, METClaim, METVarianceType from priceReason
            exists join reasonTableRef
            where reasonTableRef.Reason == priceReason.Reason
                && reasonTableRef.RecId == priceReasonRef;
    }

    VendInvoiceInfoLine invoiceInfoLine;

    select firstonly invoiceInfoLine
        where invoiceInfoLine.ItemId == _invoiceInfoLine.METVarianceItemId
        && invoiceInfoLine.ParmId == _invoiceInfoLine.ParmId
        && invoiceInfoLine.TableRefId == _invoiceInfoLine.TableRefId;

    if (!invoiceInfoLine && reason.METVarianceType == METVarianceType::QuantityVarianceNoDelivery)
    {
        select firstonly invoiceInfoLine
            where invoiceInfoLine.ItemId == _invoiceInfoLine.ItemId
            && invoiceInfoLine.ReasonTableRef == _invoiceInfoLine.ReasonTableRef
            && invoiceInfoLine.ParmId == _invoiceInfoLine.ParmId
            && invoiceInfoLine.TableRefId == _invoiceInfoLine.TableRefId;
    }

    if (reason)
    {
        lines.ReasonCode =  reason.Reason;
    }
    else if (priceReason)
    {
        lines.ReasonCode =  priceReason.Reason;
    }

    boolean qtyFailure = reason ? true : false;
    lines.ExtComment = qtyFailure ? _invoiceInfoLine.MetExtCommentQty: _invoiceInfoLine.MetExtComment;

    lines.VarianceAccount = invoiceInfoLine.METVarianceAccount;
    if (reason)
    {
        lines.Claim = reason.METClaim ? NoYes::Yes : NoYes::No;
    }
    else if (priceReason)
    {
        lines.Claim = priceReason.METClaim ? NoYes::Yes : NoYes::No;
    }
    boolean isCW = PdsGlobal::pdsIsCWItem(invoiceInfoLine.ItemId);

    lines.ItemNumber = invoiceInfoLine.ItemId;
    lines.ItemDescription = InventTable::find(invoiceInfoLine.ItemId).itemName();

    lines.InvoiceQuantity = reason ? invoiceInfoLine.ReceiveNow + _invoiceInfoLine.ReceiveNow : invoiceInfoLine.ReceiveNow;
    lines.ReceiptedQuantity = invoiceInfoLine.METReceiptedQuantity;
    if (isCW)
    {
        lines.InvoiceQuantity = invoiceInfoLine.ReceiveNow;
        lines.InvoiceRWQuantity = reason ? _invoiceInfoLine.ReceiveNow + invoiceInfoLine.METInvoiceRWQuantity : invoiceInfoLine.METInvoiceRWQuantity;
        lines.ReceiptedRWQuantity = invoiceInfoLine.METReceiptedRWQuantity;
        lines.ReceiptedRWUnit = invoiceInfoLine.METReceiptedRWUnit;
        lines.ImportedCWInvoicePrice = invoiceInfoLine.METImportedCWInvoicePrice;
        lines.ReceiptedQuantity = invoiceInfoLine.METReceiptedQuantity;
    }
    if (reason.METVarianceType == METVarianceType::QuantityVarianceNoDelivery)
    {
        lines.InvoiceQuantity = invoiceInfoLine.ReceiveNow;
    }

    lines.InvoiceCWQuantity = invoiceInfoLine.PdsCWReceiveNow;
    lines.ReceiptedCWQuantity = invoiceInfoLine.METReceiptedCWQuantity;
    //lines.InvoiceUnitPrice = reason ? invoiceInfoLine.PurchPrice : invoiceInfoLine.PurchPrice + _invoiceInfoLine.PurchPrice;

    // Incident 424968: WILO - Supply - POs - Invoice Matching - Overcharge Test - Claim Invoice did not post (potentially due to 'dot' in invoice number)
    // Issue A
    if (reason)
    {
        lines.InvoiceUnitPrice = invoiceInfoLine.PurchPrice;
    }
    else
    {
        if (_invoiceInfoLine.ReceiveNow >= 0)
        {
            lines.InvoiceUnitPrice = invoiceInfoLine.PurchPrice + _invoiceInfoLine.PurchPrice;
        }
        else
        {
            lines.InvoiceUnitPrice = invoiceInfoLine.PurchPrice - _invoiceInfoLine.PurchPrice;
        }
    }

    lines.ReceiptedUnit = invoiceInfoLine.METReceiptedUnit;
    lines.InvoiceNumber = _invoiceId;
    lines.VendAccountNumber = invoiceInfoLine.InvoiceAccount;
    lines.InvoiceLineNumber = _lineNum;

    if (reason)
    {
        lines.QuantityVariance = _invoiceInfoLine.ReceiveNow;
        lines.VarianceAmount = CurrencyExchangeHelper::amount(_invoiceInfoLine.ReceiveNow *  _invoiceInfoLine.PurchPrice, _invoiceInfoLine.CurrencyCode);
    }
    else if (priceReason)
    {
        // Incident 424968: WILO - Supply - POs - Invoice Matching - Overcharge Test - Claim Invoice did not post (potentially due to 'dot' in invoice number)
        // Issue A
        lines.PriceVariance = _invoiceInfoLine.ReceiveNow >= 0 ? _invoiceInfoLine.PurchPrice : -_invoiceInfoLine.PurchPrice;
        if (isCW)
        {
            lines.VarianceAmount = CurrencyExchangeHelper::amount((_invoiceInfoLine.PurchPrice * invoiceInfoLine.METInvoiceRWQuantity), _invoiceInfoLine.CurrencyCode);
        }
        else
        {
            lines.VarianceAmount = CurrencyExchangeHelper::amount((_invoiceInfoLine.PurchPrice * lines.InvoiceQuantity), _invoiceInfoLine.CurrencyCode);
        }
    }

    lines.insert();
}
